  "contradictory_card_ids": [],
  "prediction_basis_card_ids": ["C18","C21","C08","C15","C16","C01","C12","C19","C20","C159","C191","C189","C230"],
  "claims": [
    {
      "claim": "All visible L1 reference contexts report direct human absolute oral bioavailability values of 43-91%, all above the 20% threshold; nitrile- and fused-heteroaromatic-containing contexts (glasdegib 77.12%, AG-221 57.2%, ondansetron 50-65%, GSK1322322 57-77%) are the most relevant and support F≥20%.",
      "card_ids": ["C18","C21","C08","C15","C16","C01","C12","C19","C20"]
    },
    {
      "claim": "The closest L5 scaffold match (M11, identical imidazo[4,5-b]pyridin-2-one core with pyridin-3-yl instead of quinolin-3-yl and tetrahydropyranyl instead of 4-(2-cyanopropan-2-yl)phenyl) shows high MDCK Papp A-B of 30×10^-6 cm/s with efflux ratio 1.5, indicating high permeability and no significant efflux.",
      "card_ids": ["C159"]
    },
    {
      "claim": "Other L5 fused-heteroaromatic records show high absorptive permeability and low efflux ratios (tryptanthrin ER 1.12; M02 ER 1.1; AZD1390 ER 1.1 at 1 µM; M05/M19 Papp>10×10^-6 cm/s with ER<2; telmisartan analog 7c ER 1.27; MMB ER 0.9), supporting absorption for the query's lipophilic fused aromatic scaffold.",
      "card_ids": ["C136","C143","C178","C154","C140","C183","C179","C138"]
    },
    {
      "claim": "L6 contains no query-specific hepatic clearance measurement, but the closest imidazopyridinone records show metabolic stability: M26 shows excellent stability in human and rat liver microsomes (C191), and M13/M15 show only 9% metabolized after 15 min in human liver microsomes (C189, C230), supporting low hepatic first-pass metabolism for this core; no L6 record indicates high clearance for the query's core.",
      "card_ids": ["C191","C189","C230"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "hepatic_clearance_metabolic_stability",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C191","C189","C230"]
    }
  ],
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement exists for the query molecule itself.",
    "No query-specific solubility or dissolution data; high logD (5.89) suggests poor aqueous solubility, but dose and formulation are unknown.",
    "No query-specific hepatic clearance or metabolic stability data; the closest L6 records are for analogs with different substituents.",
    "No query-specific intestinal metabolism or efflux data; the closest L5 scaffold (M11) is close but not identical.",
    "Prandial state and formulation for the query are unknown; food effects cannot be excluded."
  ],
  "decision_summary": "L1/L2 direct human absolute BA values (43-91%) and L5 permeability/efflux data, including a near-identical imidazopyridinone scaffold with high Papp and low efflux ratio, support F≥20%. L6 adds supportive metabolic-stability evidence for the same imidazopyridinone core, indicating low hepatic first-pass metabolism. No affirmative F<20% evidence exists; prediction remains high with moderate confidence."
}

